insert into public.emergency_countries (country_code, name_en, wave, general_number, general_number_src, sds_rule_kind, sds_rule_summary, sds_rule_source_url, sds_rule_checked_on, state) values
  ('AT', 'Austria', 2, null, null, 'poison_centre_number_allowed', 'Chemicals Act (ChemG 1996) section 25(4), consolidated version of 15 October 2026: the safety data sheet must be in German and, for products placed on the market in Austria, section 1.4 must name an emergency information service that answers in German round the clock. The text does not name the Poisons Information Centre (VIZ). The Environment Agency helpdesk names the VIZ as an option for firms that cannot run their own service; the VIZ offers its number under a paid agreement whose annual fee depends on the number of safety data sheets. An earlier version of the Act, in force until July 2018, required the VIZ number; the current version does not.', 'https://www.ris.bka.gv.at/eli/bgbl/i/1997/53/P25/NOR40228395', '2026-10-15', 'draft'),
  ('BE', 'Belgium', 2, null, null, 'national_number_listed', 'The Belgian Poison Centre says in its own FAQ (18 July 2025) that the number of an official advisory body is given in section 1.4 where one exists in the Member State of supply, that it fills this role for Belgium, and names its public number for that section, free and open round the clock. No Belgian government text on an own-number or language requirement was found; the health ministry pages could not be read.', 'https://www.centreantipoisons.be/faq-numero-durgence-sur-fiche-de-donnees/', '2026-10-15', 'draft'),
  ('BG', 'Bulgaria', 2, null, null, 'national_number_listed', 'The Ministry of Environment and Water page on the CLP emergency number lists the National Toxicology Centre at the Pirogov hospital as the national emergency contact. It does not say whether suppliers must or may use it in section 1.4 and says nothing on hours or language. National rules are reported to be under amendment.', 'https://www.moew.government.bg/en/prevention/chemicals/classification-clp/emergency-number/', '2026-10-15', 'draft'),
  ('CY', 'Cyprus', 2, '1401', 'https://www.mlsi.gov.cy/mlsi/dli/dliup.nsf/All/857596C003507683C2257EAD00283E1C', 'national_number_listed', 'The Department of Labour Inspection says suppliers must put the Cyprus Poison Centre number in section 1.4 for products on the Cyprus market; the number is free and for health or medical emergencies only. The Greek-language safety data sheet must be uploaded with each notification. The page does not say who runs the service or its hours, and does not say whether an own number of the supplier may be added.', 'https://www.mlsi.gov.cy/mlsi/dli/dliup.nsf/All/857596C003507683C2257EAD00283E1C', '2026-10-15', 'draft'),
  ('CZ', 'Czechia', 2, null, null, 'poison_centre_number_allowed', 'Ministry of Health guidance (version of 20 April 2021) says the Toxicological Information Centre (TIS) is the Czech body that receives hazardous-mixture information and recommends that suppliers list its contact details in safety data sheets; it is not a mandatory own-number rule. A 2015 presentation of the National Institute of Public Health says that where a Member State has an official advisory body its number is stated, that the number is for threats to life and health only, and that the text must be in Czech (older source).', 'https://mzd.gov.cz/wp-content/uploads/2020/12/metodicky-vyklad_oznamovani-NCH_priloha-VIII-CLP_v3.pdf', '2026-10-15', 'draft'),
  ('DK', 'Denmark', 2, null, null, 'no_rule_found', 'The Danish Environmental Protection Agency pages (updated November 2025) set no rule for the number in section 1.4; the only language rule found is that safety data sheets must be available in Danish. Giftlinjen is described as the poison information service that receives mixture data under Article 45 CLP.', 'https://mst.dk/erhverv/sikker-kemi/kemikalier/reach-og-clp/faa-overblik-over-reach/sikkerhedsdatablade-og-eksponeringsscenarier', '2026-10-15', 'draft'),
  ('EE', 'Estonia', 2, null, null, 'national_number_listed', 'The Health Board has a page titled "Data for Section 1.4 of Safety Data Sheet" (updated 8 November 2024) that gives the Poison Information Centre numbers and the national number 112 for use there. It states no requirement for an own number, language or conditions of use. A separate page for chemical manufacturers recommends printing the Centre number on products and says adding it is free.', 'https://terviseamet.ee/en/chemical-and-product-safety/data-for-safety-data-sheet', '2026-10-15', 'draft'),
  ('FI', 'Finland', 2, null, null, 'poison_centre_number_allowed', 'HUS says importers may print the number of the Poison Information Centre on packaging and safety data sheets as the emergency contact, free of charge, provided the mixture is notified to the Centre (page updated 1 November 2024). The page does not mention section 1.4, opening hours or which of its numbers to use. Tukes says safety data sheets must be in Finnish and/or Swedish depending on the recipient and does not address the emergency number.', 'https://www.hus.fi/en/patient/how-get-help/poison-information-center/chemical-products-information-manufactures-and', '2026-10-15', 'draft'),
  ('GR', 'Greece', 2, null, null, 'no_rule_found', 'The letter of the General Chemical State Laboratory of 22 December 2020 does not mention section 1.4; it says the Poison Centre was to be added as a national body with access to the ECHA notification database, pending a ministerial decision. No Greek page found sets a rule for the emergency number or the language of the sheet.', 'https://aade.gr/sites/default/files/2021-04/VIII-CLP-22.12.2020_signed.pdf', '2026-10-15', 'draft'),
  ('HR', 'Croatia', 2, null, null, 'poison_centre_number_allowed', 'A 2009 rulebook on the content of safety data sheets says section 1.4 should give the company number and/or that of the competent official advisory body, and that numbers staffed in office hours only must be stated as such; whether it is still in force was not confirmed. The page of the Croatian Institute of Public Health says a safety data sheet must be entirely in Croatian and describes a separate Croatian filing with a fee.', 'https://narodne-novine.nn.hr/clanci/sluzbeni/2009_03_39_900.html', '2026-10-15', 'draft'),
  ('HU', 'Hungary', 2, null, null, 'national_number_listed', 'The page of the Health Toxicology Information Service (NNGYK) says its number must be printed in section 1.4 of safety data sheets for hazardous substances and mixtures marketed in Hungary; the legal text itself was not checked.', 'https://nngyk.gov.hu/hu/egeszsegugyi-toxikologiai-tajekoztato-szolgalat/egeszsegugyi-toxikologiai-tajekoztato-szolgalat.html', '2026-10-15', 'draft'),
  ('IE', 'Ireland', 2, null, null, 'poison_centre_number_allowed', 'The National Poisons Information Centre (NPIC) states that a poison-centre emergency number is obligatory in section 1.4 for notified hazardous mixtures and that an additional external number may be added. Its number can be used only after notification, a signed agreement and indemnity, and an annual retainer (EUR 650 excluding VAT per company, EUR 200 for companies notifying fewer than 10 products; page modified 11 July 2024). Suppliers should state that the NPIC line is open from 8 am to 10 pm every day.', 'https://poisons.ie/?p=158', '2026-10-15', 'draft'),
  ('IS', 'Iceland', 2, null, null, 'national_number_listed', 'The FAQ of the Environment and Energy Agency says a safety data sheet written in English must include Icelandic emergency-response information in section 1.4 and names the Poison Centre at the University Hospital with its number. The FAQ states this for English-language sheets only; another agency document says sheets from suppliers must be in Icelandic.', 'https://ust.is/english/industry/chemicals/frequently-asked-questions/safety-data-sheets/', '2026-10-15', 'draft'),
  ('LI', 'Liechtenstein', 2, null, null, 'no_rule_found', 'No Liechtenstein rule on the emergency number in section 1.4 was found. The leaflet of the Office of Environment (version 4.0, July 2015) takes the EEA safety data sheet as the baseline and mentions the Swiss number 145 only among Swiss adaptations for the Swiss market. No official page links Liechtenstein to the Swiss poison information service or to the Austrian one.', 'https://www.llv.li/serviceportal2/amtsstellen/amt-fuer-umwelt/umweltschutz/chemikalien/mb-ec02-sicherheitsdatenblatt-v4-201507docx.pdf', '2026-10-15', 'draft'),
  ('LT', 'Lithuania', 2, null, null, 'no_rule_found', 'No Lithuanian official page was found on whether a national-language service or an own number is required for section 1.4. The Environmental Protection Agency is the Article 45 CLP body but does not run the poison line; the line is run by the State Medicines Control Agency.', 'https://vvkt.lrv.lt/lt/informacija-apie-apsinuodijimus/konsultacijos-apsinuodijimu-klausimais/', '2026-10-15', 'draft'),
  ('LU', 'Luxembourg', 2, null, null, 'national_number_listed', 'Luxembourg has no poison centre of its own; since an agreement of 2 June 2015 the Belgian Poison Centre serves it. The Belgian centre names a separate Luxembourg number for section 1.4 (free, round the clock). No Luxembourg authority page read states a rule for the emergency number in section 1.4.', 'https://www.centreantipoisons.be/faq-numero-durgence-sur-fiche-de-donnees/', '2026-10-15', 'draft'),
  ('LV', 'Latvia', 2, null, null, 'no_rule_found', 'No official page on the emergency number in section 1.4 was found. Cabinet Regulation No. 795 asks companies for an emergency-contact unit with telephone and e-mail, but as part of the report to the chemicals database of the Latvian Environment, Geology and Meteorology Centre, not for the safety data sheet. The Centre receives product data under Article 45 CLP but does not answer poison calls. A poison and drug information centre at a Riga hospital is named in official database documents, but no official page with its number was found.', 'https://likumi.lv/ta/id/279100', '2026-10-15', 'draft'),
  ('MT', 'Malta', 2, null, null, 'no_rule_found', 'No official page found says anything on section 1.4. The FAQ and charter of the Malta National Poisons Centre do not address safety data sheets or labels, and the helpdesk page of the competent authority does not either.', 'https://mnpc.gov.mt/en/faqs/', '2026-10-15', 'draft'),
  ('NO', 'Norway', 2, null, null, 'national_number_listed', 'The Norwegian Environment Agency says the emergency number must be given in section 1.4 and that safety data sheets must be in Norwegian, without naming a number. The Poisons Information Centre page on helsenorge.no (2020) tells producers and importers to enter its number in section 1.4 because it is the only poison centre in Norway.', 'https://www.helsenorge.no/en/poison-information/', '2026-10-15', 'draft'),
  ('PL', 'Poland', 2, null, null, 'no_rule_found', 'No Polish page was found that sets a rule for section 1.4 of a safety data sheet. The sanitary inspectorate pages only name the emergency telephone number as a section heading and say the text must be in Polish, without saying whether that covers the telephone service; the EU rules for section 1.4 apply directly and no additional Polish rule was found. The Bureau for Chemical Substances is the Article 45 CLP body and its pages carry no emergency number. Several toxicology units run services of their own; the Kraków unit sells a dedicated emergency number for safety data sheets by contract.', 'https://www.gov.pl/web/psse-warszawa/co-to-jest-karta-charakterystyki-i-jak-ja-czytac', '2026-10-15', 'draft'),
  ('PT', 'Portugal', 2, null, null, 'no_rule_found', 'The page of the poison information centre (INEM) does not say whether its number may or must go in section 1.4. A leaflet hosted by the Portuguese Environment Agency says the unique formula identifier must be on the label and the sheet and that their content must match the notification; no Portuguese rule on the emergency number was found.', 'https://apambiente.pt/sites/default/files/_Prevencao_gestao_riscos/Quimicos/UFI/folheto_notificacao_centro_antivenenos_vf.pdf', '2026-10-15', 'draft'),
  ('RO', 'Romania', 2, null, null, 'no_rule_found', 'No official Romanian page on section 1.4 was found. The Toxicology Information Centre at the Emergency Clinical Hospital of Bucharest is named in the ECHA table of appointed bodies; the hospital site could not be read, and no official page confirms that the centre answers calls rather than only receiving notifications.', 'https://poisoncentres.echa.europa.eu/appointed-bodies', '2026-10-15', 'draft'),
  ('SE', 'Sweden', 2, '112', 'https://giftinformation.se/foretag/nya-kemiska-produkter/', 'national_number_listed', 'The Swedish Poisons Information Centre (GIC) says safety data sheets should list 112 with a request for Giftinformation; companies connected to Kemiakuten may use its number instead. GIC does not plan to charge for use of its number on safety data sheets. The Swedish Chemicals Agency says the sheet should carry the number of the official advisory body, for Sweden GIC, and that the number to list is 112. Neither page states a round-the-clock or language rule.', 'https://giftinformation.se/foretag/nya-kemiska-produkter/', '2026-10-15', 'draft'),
  ('SI', 'Slovenia', 2, null, null, 'no_rule_found', 'No Slovenian official page addresses the emergency number in section 1.4; a 2022 rule only says suppliers must give extra information from the safety data sheet on request. The Centre for Clinical Toxicology and Pharmacology at the Ljubljana university hospital is named on gov.si as a receiving body for mixture information; no official page with a poison-line number was found.', 'https://www.gov.si/zbirke/storitve/predlozitev-informacij-o-kemijskih-zmeseh/', '2026-10-15', 'draft'),
  ('SK', 'Slovakia', 2, null, null, 'national_number_listed', 'The National Toxicological Information Centre says on its own page (modified 10 September 2025) that listing its emergency number in section 1.4 is, for now, free of charge in Slovakia. The page does not describe it as mandatory and says nothing on own-number or language rules.', 'https://www.ntic.sk/produktove-informacie/', '2026-10-15', 'draft');
insert into public.emergency_services (country_code, slug, kind, name, operator, phone_display, phone_tel, hours_kind, hours_note, audience, languages, sds_use, sds_use_note, cost_note, source_url, source_date, verification, checked_on, state, sort) values
  ('PL', 'krakow-uj-cm', 'poison_centre', 'Poison centre Kraków (Toxicology Information and Laboratory Analysis Unit)', 'Jagiellonian University Medical College', '(12) 411 99 99', '+48124119999', '24_7', null, 'public_and_professionals', '{}', 'public_line', 'The page says nothing about using this number in a safety data sheet. The unit separately offers a dedicated emergency number for safety data sheets to manufacturers, importers and distributors, by contract and on request; a toxicology doctor answers it round the clock.', null, 'https://oit.cm.uj.edu.pl/o-pracowni/kontakt/', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('PL', 'poznan-raszeja', 'poison_centre', 'Poison information centre Poznań (Toxicology Department, Raszeja Hospital)', 'Franciszek Raszeja City Hospital', '61 847 69 46', '+48618476946', 'not_stated', null, 'public_and_professionals', '{}', 'public_line', 'Printed as the emergency telephone of the department, which keeps 24-hour duty as a supervisory centre for acute poisonings in the Wielkopolskie, Lubuskie and Zachodniopomorskie regions; the page does not say which of its numbers is staffed round the clock. The page names doctors, rescuers, health workers, chemical-safety institutions and the general public as users.', null, 'https://raszeja.poznan.pl/service/oddzial-toksykologiczny/', null, 'confirmed', '2026-10-15', 'draft', 1),
  ('PL', 'gdansk-pct', 'poison_centre', 'Pomorskie Toxicology Centre, Gdańsk', 'Pomorskie Centrum Toksykologii Sp. z o.o.', '058 682 04 04', '+48586820404', 'not_stated', null, 'not_stated', '{}', 'listed_in_register', 'Printed with the label "Alarm" on the list of toxicological information centres of the Office for Registration of Medicinal Products. The page carries no date and matches an archived copy from 2015; it was not cross-checked on the centre own site, which could not be read.', null, 'https://www.gov.pl/web/urpl/adresy-osrodkow-informacji-toksykologicznej', null, 'dated_source', '2026-10-15', 'draft', 2),
  ('PL', 'warszawa-halinow', 'poison_centre', 'Poison control centre Warsaw (Ośrodek Kontroli Zatruć), Halinów', null, '607 218 174', '+48607218174', 'not_stated', null, 'not_stated', '{}', 'listed_in_register', 'Printed with the label "Alarm" on the list of toxicological information centres of the Office for Registration of Medicinal Products. The page carries no date and matches an archived copy from 2015; no site of the centre itself was found.', null, 'https://www.gov.pl/web/urpl/adresy-osrodkow-informacji-toksykologicznej', null, 'dated_source', '2026-10-15', 'draft', 3),
  ('PL', 'lodz', 'poison_centre', 'Toxicology unit Łódź (Central Clinical Hospital of the Medical University)', 'Centralny Szpital Kliniczny Uniwersytetu Medycznego w Łodzi', '661 442 576', '+48661442576', '24_7', null, 'not_stated', '{}', 'professionals_line', 'Printed as the round-the-clock toxicology duty line. The unit page describes the service as support for doctors treating patients in other facilities; the duty page does not say whether others may call. A second number for the toxicologist on-site hours (7:30-15:00) is not listed here.', null, 'https://csk.umed.pl/kliniki-i-oddzialy/pododdzial-toksykologii/', '2025-09-02', 'confirmed', '2026-10-15', 'draft', 4),
  ('PL', 'lublin', 'poison_centre', 'Toxicology information line, Clinical Toxicology-Cardiology and Internal Diseases Ward, Lublin', null, '517 619 306', '+48517619306', '24_7', null, 'public_and_professionals', '{}', 'public_line', 'The page offers round-the-clock telephone toxicology information to other care facilities and to private individuals. The hospital name is not stated on the page.', null, 'https://szpital.lublin.pl/oddzialy-al-krasnicka-100/208-kliniczny-oddzial-toksykologiczno-kardiologiczny-i-chorob-wewnetrznych.html', '2026-06-11', 'confirmed', '2026-10-15', 'draft', 5),
  ('PL', 'sosnowiec', 'poison_centre', 'Toxicology Ward with Acute Poisoning Centre, Sosnowiec', 'Wojewódzki Szpital Specjalistyczny nr 5 im. św. Barbary', '32 368 21 16 (also +48 538 81 99 61)', '+48323682116', '24_7', null, 'not_stated', '{}', 'professionals_line', 'The unit page says doctors are on duty round the clock and addresses doctors of healthcare facilities; it does not say whether the public may call. It also prints 32 368 20 00 ext. 2116.', null, 'https://www.wss5.pl/content/oddzial-toksykologii-z-osrodkiem-ostrych-zatruc', null, 'confirmed', '2026-10-15', 'draft', 6),
  ('PL', 'wroclaw', 'poison_centre', 'Toxicology and Internal Diseases Ward, Wrocław (Marciniak Hospital)', 'Dolnośląski Szpital Specjalistyczny im. T. Marciniaka – Centrum Medycyny Ratunkowej', '71 306 48 41, 71 306 48 42', '+48713064841', '24_7', null, 'professionals_only', '{}', 'professionals_line', 'The page invites doctors from other facilities to call for advice.', null, 'https://www.szpital-marciniak.wroclaw.pl/p,168,oddzial-toksykologii-i-chorob-wewnetrznych', null, 'confirmed', '2026-10-15', 'draft', 7),
  ('AT', 'viz', 'poison_centre', 'Poisons Information Centre (VIZ)', 'Gesundheit Österreich GmbH', '01 406 43 43', '+4314064343', '24_7', null, 'public_and_professionals', '{}', 'by_contract_only', 'The VIZ offers its round-the-clock German-language number for section 1.4 under a paid agreement (the annual fee depends on the number of safety data sheets; no figures are given). It says safety data sheets not sent to it limit its ability to advise.', null, 'https://goeg.at/Vergiftungsinformation', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('BE', 'centre-antipoisons', 'poison_centre', 'Belgian Poison Centre (Centre Antipoisons / Antigifcentrum)', 'Centre Antipoisons, foundation of public utility', '070 245 245', '+3270245245', '24_7', null, 'public_and_professionals', '{}', 'national_body_for_sds', 'The FAQ of the Centre says to enter this number in section 1.4 for Belgium. The same number also takes calls about animals (stated hours for animals: weekdays 8:00-16:00, weekends and holidays 10:00-16:00).', 'Free number according to the Centre.', 'https://www.centreantipoisons.be/faq-numero-durgence-sur-fiche-de-donnees/', '2025-07-18', 'confirmed', '2026-10-15', 'draft', 0),
  ('LU', 'centre-antipoisons-lu', 'poison_centre', 'Belgian Poison Centre, Luxembourg line', 'Belgian Poison Centre, under an agreement of 2 June 2015 with the Luxembourg Ministry of Health', '8002 5500', '+35280025500', '24_7', null, 'public_and_professionals', '{}', 'national_body_for_sds', 'The FAQ of the Belgian Centre lists this number for section 1.4 for Luxembourg; the ministry pages call it the poison-centre number and do not mention safety data sheets.', 'Free according to the ministry and the Centre.', 'https://santesecu.public.lu/fr/urgences-gardes/autres-urgences.html', '2025-07-28', 'confirmed', '2026-10-15', 'draft', 0),
  ('DK', 'giftlinjen', 'poison_centre', 'Giftlinjen (Danish Poison Line)', 'Bispebjerg Hospital, Department of Clinical Pharmacology (Capital Region)', '82 12 12 12', '+4582121212', '24_7', null, 'public_and_professionals', '{}', 'public_line', 'National service; covers Denmark, Danish ships, the Faroe Islands and Greenland; does not advise on animals; waits may be long. The page says nothing about safety data sheets.', null, 'https://www.bispebjerghospital.dk/giftlinjen/om-giftlinjen/Sider/default.aspx', '2025-05-19', 'confirmed', '2026-10-15', 'draft', 0),
  ('FI', 'hus-poison-centre', 'poison_centre', 'Poison Information Centre (Myrkytystietokeskus)', 'HUS Helsinki University Hospital', '0800 147 111 (free), 09 471 977 (standard rate)', '+3589471977', '24_7', 'Open every day of the year; authorities and media are served on weekdays 8:30-15:00.', 'public_and_professionals', '{}', 'national_body_for_sds', 'HUS says importers may print the number of the Centre on packaging and safety data sheets as the emergency contact, free of charge, if the mixture is notified to the Centre.', 'The 0800 number is labelled free of charge, the 09 number standard rate.', 'https://www.hus.fi/potilaalle/sairaalat-ja-toimipisteet/myrkytystietokeskus', '2026-08-27', 'confirmed', '2026-10-15', 'draft', 0),
  ('NO', 'giftinformasjonen', 'poison_centre', 'Giftinformasjonen (Norwegian Poisons Information Centre)', 'Norwegian Institute of Public Health (FHI)', '22 59 13 00', '+4722591300', '24_7', null, 'public_and_professionals', '{}', 'national_body_for_sds', 'The helsenorge.no page for producers and importers says to enter this number in section 1.4 because it is the only poison centre in Norway. Every page found that prints this number dates from 2016-2020; recheck before publishing.', null, 'https://www.helsenorge.no/en/poison-information/', '2020-06-29', 'dated_source', '2026-10-15', 'draft', 0),
  ('SE', 'gic', 'poison_centre', 'Giftinformationscentralen (GIC)', 'Swedish Medical Products Agency (Läkemedelsverket)', '112 (ask for Poison Information), 010-456 6700', '+46104566700', '24_7', 'Acute and less urgent cases round the clock; general and preventive questions on weekdays 9:00-17:00 on the same number.', 'public_and_professionals', '{}', 'national_body_for_sds', 'GIC says safety data sheets should list 112 with a request for Giftinformation; it does not plan to charge for use of its number on safety data sheets.', 'Free apart from normal telephone charges.', 'https://giftinformation.se/servicemeny/in-english/', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('SE', 'gic-healthcare', 'poison_centre', 'GIC healthcare line', 'Swedish Medical Products Agency (Läkemedelsverket)', '010-456 67 19', '+46104566719', '24_7', null, 'professionals_only', '{}', 'professionals_line', 'Line for healthcare staff.', null, 'https://giftinformation.se/lakare/', null, 'confirmed', '2026-10-15', 'draft', 1),
  ('SE', 'kemiakuten', 'national_helpdesk', 'Kemiakuten', 'GIC, funded by the chemical industry', '020-99 60 00 (from abroad +46 8 33 70 43)', '+468337043', 'not_stated', null, 'not_stated', '{}', 'national_body_for_sds', 'Advice for rescue services and others involved in chemical accidents. GIC says companies connected to Kemiakuten may list its number on safety data sheets instead of 112; the page read does not describe how a company connects.', null, 'https://giftinformation.se/foretag/kemiakuten/', '2025-12-01', 'confirmed', '2026-10-15', 'draft', 2),
  ('IS', 'eitrunarmidstod', 'poison_centre', 'Poison Information Centre (Eitrunarmiðstöð)', 'Landspítali University Hospital', '543 2222', '+3545432222', '24_7', 'Open all year; clinical pharmacists answer 08:00-20:00 and the emergency department covers other hours.', 'public', '{}', 'national_body_for_sds', 'The Environment and Energy Agency names this number for section 1.4 in its FAQ for English-language safety data sheets. The page says to call 112 in an emergency.', null, 'https://island.is/s/landspitali/eitrunarmidstod', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('EE', 'murgistusteabekeskus', 'poison_centre', 'Poison Information Centre (Mürgistusteabekeskus)', 'Health Board (Terviseamet)', '16662 (from abroad +372 794 3794)', '+3727943794', '24_7', null, 'public_and_professionals', '{}', 'national_body_for_sds', 'The Health Board page "Data for Section 1.4 of Safety Data Sheet" gives this number and 112 for use in the section; a page for manufacturers recommends printing 16662 on products and says adding it is free.', 'Official pages disagree: the Health Board page says free for all callers; the 16662.ee home page speaks of the local-call rate; another 16662.ee page says free but carriers may charge.', 'https://terviseamet.ee/en/chemical-and-product-safety/data-for-safety-data-sheet', '2024-11-08', 'confirmed', '2026-10-15', 'draft', 0),
  ('LT', 'vvkt-poison-information', 'poison_centre', 'Pharmacovigilance and Poison Information Department', 'State Medicines Control Agency (VVKT), Ministry of Health', '+370 5 236 2052', '+37052362052', '24_7', null, 'public_and_professionals', '{}', 'public_line', 'The page says nothing about safety data sheets. The Environmental Protection Agency, which receives product notifications, does not run the line.', null, 'https://vvkt.lrv.lt/lt/informacija-apie-apsinuodijimus/konsultacijos-apsinuodijimu-klausimais/', '2026-04-08', 'confirmed', '2026-10-15', 'draft', 0),
  ('CZ', 'tis', 'poison_centre', 'Toxicological Information Centre (TIS)', 'Department of Occupational Medicine, General University Hospital in Prague and First Faculty of Medicine, Charles University', '224 91 92 93, 224 91 54 02', '+420224919293', '24_7', 'Stated on the page of the hospital; the site of the centre gives no hours.', 'public_and_professionals', '{}', 'national_body_for_sds', 'Ministry of Health guidance (2021) recommends listing the Centre in safety data sheets and notes that some suppliers cite it in section 1.4 for industrial-use mixtures; it is not mandatory.', null, 'https://www.tis-cz.cz', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('SK', 'ntic', 'poison_centre', 'National Toxicological Information Centre (NTIC)', 'University Hospital Bratislava', '+421 2 5477 4166, +421 911 166 066', '+421254774166', '24_7', null, 'public_and_professionals', '{}', 'national_body_for_sds', 'NTIC says listing its number in section 1.4 is free of charge in Slovakia for now; the page does not call it mandatory.', null, 'https://www.ntic.sk/kontakt/', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('HU', 'ettsz', 'poison_centre', 'Health Toxicology Information Service (ETTSZ)', 'National Center for Public Health and Pharmacy (NNGYK)', '+36 80 201 199', '+3680201199', '24_7', null, 'public_and_professionals', '{}', 'national_body_for_sds', 'The page says this number must be printed in section 1.4 of safety data sheets for hazardous substances and mixtures marketed in Hungary.', 'Free, and callable only from within Hungary according to the page.', 'https://nngyk.gov.hu/hu/egeszsegugyi-toxikologiai-tajekoztato-szolgalat/egeszsegugyi-toxikologiai-tajekoztato-szolgalat.html', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('HR', 'cko-imi', 'poison_centre', 'Poison Control Centre (Centar za kontrolu otrovanja)', 'Institute for Medical Research and Occupational Health (IMI), Zagreb', '01 2348 342', '+38512348342', '24_7', null, 'public_and_professionals', '{}', 'public_line', 'Described as a 24-hour telephone information service, mainly for health institutions and staff and also open to citizens and users abroad. The page does not tie the number to safety data sheets and shows no date (footer 2016, newest annual report 2024).', null, 'https://www.imi.hr/hr/centar-za-kontrolu-otrovanja/', null, 'dated_source', '2026-10-15', 'draft', 0),
  ('HR', 'hzjz-oncall', 'poison_centre', 'Toxicology Service on-call line (HZJZ)', 'Croatian Institute of Public Health (HZJZ)', '098 405 636', '+38598405636', '24_7', 'Labelled on-call round the clock, for emergencies only.', 'not_stated', '{}', 'listed_in_register', 'Listed among the contact numbers of the Toxicology Service and not tied to section 1.4. The Service keeps the mixtures database used by the Poison Control Centre. The page shows no date.', null, 'https://www.hzjz.hr/sluzba-za-toksikologiju/', null, 'dated_source', '2026-10-15', 'draft', 1),
  ('BG', 'pirogov-toxicology', 'poison_centre', 'National Toxicology Centre (Pirogov Hospital)', 'UMBALSM N. I. Pirogov EAD, Sofia', '+359 2 9154 233', '+35929154233', 'not_stated', null, 'not_stated', '{}', 'listed_in_register', 'The Ministry of Environment and Water page shows this number under "Emergency number" on a line labelled "Emergency number/ fax", so it may be a fax line; the hospital own pages do not print it. A hospital page of 2017 says its Information Centre gives specialised information on acute poisonings round the clock, without a number.', null, 'https://www.moew.government.bg/en/prevention/chemicals/classification-clp/emergency-number/', null, 'unconfirmed', '2026-10-15', 'draft', 0),
  ('PT', 'ciav', 'poison_centre', 'Centro de Informação Antivenenos (CIAV)', 'INEM (National Institute for Medical Emergency)', '800 250 250', '+351800250250', '24_7', null, 'public_and_professionals', '{}', 'public_line', 'The page does not say whether the number may or must go in section 1.4. The leaflet of the Environment Agency also prints it as the CIAV emergency contact.', 'Free call according to the page.', 'https://www.inem.pt/category/servicos/centro-de-informacao-antivenenos/', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('IE', 'npic-public', 'poison_centre', 'National Poisons Information Centre, public line', 'NPIC, Beaumont Hospital, Dublin', '01 809 2166', '+35318092166', 'stated_other', 'The home page says 8 am to 10 pm; the public page states no hours.', 'public', '{}', 'by_contract_only', 'The NPIC pages do not say which number goes in section 1.4. They say NPIC supplies the number for the sheet after notification, a signed agreement and indemnity, and an annual retainer (EUR 650 excluding VAT per company, EUR 200 for companies notifying fewer than 10 products).', null, 'https://poisons.ie/public/', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('IE', 'npic-professionals', 'poison_centre', 'NPIC Healthcare Professional Poisons Line', 'NPIC, Beaumont Hospital, Dublin', '01 809 2566', '+35318092566', '24_7', 'Staffed in Dublin 8 am to 10 pm; calls outside those hours transfer to the UK National Poisons Information Service.', 'professionals_only', '{}', 'professionals_line', 'The number appears on the page in image alt text only.', null, 'https://poisons.ie/professionals/', null, 'confirmed', '2026-10-15', 'draft', 1),
  ('MT', 'mnpc', 'poison_centre', 'National Poisons Helpline (Malta National Poisons Centre)', 'Government of Malta, Malta National Poisons Centre', '1774 (from abroad +356 2559 4600)', '+35625594600', 'stated_other', 'Helpline 08:00-20:00 every day including Sundays and public holidays; clinical toxicologists advise doctors 24 hours a day (no separate number listed). Outside helpline hours the page directs the public to a health centre or A&E.', 'public_and_professionals', '{}', 'public_line', 'The page says nothing about safety data sheets.', null, 'https://mnpc.gov.mt/en/', null, 'confirmed', '2026-10-15', 'draft', 0),
  ('GR', 'poison-centre-kyriakou', 'poison_centre', 'Greek National Poison Information Centre', 'P. and A. Kyriakou Children Hospital, Athens (Ministry of Health)', '210 779 3777', '+302107793777', '24_7', null, 'public_and_professionals', '{}', 'public_line', 'Source is the English-language information PDF of the hospital (file path dated February 2019) to which the ECHA table points; the current hospital page gives no poison-line number. ECHA calls it a consultation line, the PDF an emergency number. The PDF says the number is printed on marketed products and drugs in Greece and does not mention safety data sheets.', null, 'https://aglaiakyriakou.gr/wp-content/uploads/2019/02/Site-KD-English-Version-28_02_2019.pdf', '2019-02', 'dated_source', '2026-10-15', 'draft', 0);
