-- 116 - emergency lines, second wave: official bodies for the 25 other countries of the ECHA table of appointed bodies (2026-10-15).
--
-- Data only; the tables come from 113. Every row is a draft: nothing is public until a page exists and rows are set live.
-- Each number was read on the page named in source_url on 2026-10-15 and is stored as its own row with that source.
-- verification = 'dated_source' where the source is old or undated (Poland: Gdansk and Halinow, an authority list without a date;
-- Norway: pages of 2016-2020; Croatia: pages without a date; Greece: a PDF of 2019).
-- verification = 'unconfirmed' only for Bulgaria: the ministry page labels the number "Emergency number/ fax"; such a row cannot go live.
-- Rules applied in this wave:
--   * lines for professionals only are stored only when the service prints the number on its own public page
--     (not stored: Denmark, number visible after login only; Norway, number only in an annual report);
--   * Cyprus (1401) and Sweden (112) are stored as the general number of the country, with the source;
--   * Cyprus, Latvia, Liechtenstein, Romania and Slovenia have no service row: no confirmed number, or no number in international form;
--   * one row = one service; a second number of the same service is shown in phone_display, phone_tel holds the first number
--     that can be dialled from abroad.
-- Vocabularies are kept in code, not in the database. New values in this wave: sds_rule_kind 'poison_centre_number_allowed' and
-- 'no_rule_found'; sds_use 'professionals_line'.
-- Applied through the Supabase MCP on 2026-10-15; checked as the anon role afterwards (0 rows visible).
begin;



commit;

-- Check: 25 countries and 31 services in wave 2, all drafts
-- (expected: PL 8, SE 3, HR 2, IE 2, sixteen countries with 1, CY LI LV RO SI with 0).
select c.country_code, c.state, count(s.id) as services
from public.emergency_countries c left join public.emergency_services s using (country_code)
where c.wave = 2
group by 1, 2 order by 3 desc, 1;

